16	// 本文件为数据目录独占使用补回归保障，Unix（flock）与 Windows
17	//（LockFileEx）下同样适用：
18	//
19	//   - 同一进程内第二次打开同一目录立即失败，返回非空错误与空句柄；
20	//   - 另一个独立进程持有同一目录时，本进程打开同样立即失败，而不是等待
21	//     对方关闭；
22	//   - 被拒绝的调用不影响原使用者：登记患者、草稿/生效/更正、查询历史与
23	//     审计全部照常，已提交内容保持原样，占用状态也不改变；
24	//   - 不同目录互不影响；
25	//   - Close 后同位置可重新打开并读到完整数据；目录里残留的锁标记文件
26	//     本身不代表仍有人占用；
27	//   - 数据无法读取或格式不受支持时，Open 返回错误和空句柄并释放占用，
28	//     调用方修正数据后可再次打开。
29	
30	const (
31		holderModeEnv = "CLINICAL_LOCK_TEST_HOLDER"
32		holderDirEnv  = "CLINICAL_LOCK_TEST_DIR"
33	)
34	
35	// alreadyInUseMsg 是两种平台实现共用的占用错误片段。
36	const alreadyInUseMsg = "already in use"
37	
38	// TestMain 让测试二进制可以作为“独立持锁进程”运行：父进程启动自身副本，
39	// 子进程 Open 指定目录并持有，直到父进程关闭其标准输入才 Close 退出。
40	func TestMain(m *testing.M) {
41		if os.Getenv(holderModeEnv) == "1" {
42			os.Exit(runHolderProcess())
43		}
44		os.Exit(m.Run())
45	}
46	
47	func runHolderProcess() int {
48		dir := os.Getenv(holderDirEnv)
49		out := bufio.NewWriter(os.Stdout)
50		s, err := Open(dir)
51		if err != nil {
52			fmt.Fprintf(out, "ERROR: %v\n", err)
53			_ = out.Flush()
54			return 1
55		}
56		fmt.Fprintln(out, "READY")
57		if err := out.Flush(); err != nil {
58			_ = s.Close()
59			return 1
60		}
61		// 阻塞到父进程关闭标准输入，期间一直持有目录占用。
62		_, _ = io.Copy(io.Discard, os.Stdin)
63		if err := s.Close(); err != nil {
64			fmt.Fprintf(os.Stderr, "holder close: %v\n", err)
65			return 1
66		}
67		return 0
68	}
69	
70	// holder 是一个持有数据目录占用的独立进程。
71	type holder struct {
72		cmd     *exec.Cmd
73		stdin   io.WriteCloser
74		readyCh chan string
75	}
76	
77	func spawnHolder(t *testing.T, dir string) *holder {
78		t.Helper()
79		exe, err := os.Executable()
80		if err != nil {
81			t.Fatalf("locate test binary: %v", err)
82		}
83		cmd := exec.Command(exe, "-test.run", "^TestMain$")
84		cmd.Env = append(os.Environ(), holderModeEnv+"=1", holderDirEnv+"="+dir)
85		stdin, err := cmd.StdinPipe()
86		if err != nil {
87			t.Fatalf("holder stdin pipe: %v", err)
88		}
89		stdout, err := cmd.StdoutPipe()
90		if err != nil {
91			t.Fatalf("holder stdout pipe: %v", err)
92		}
93		cmd.Stderr = os.Stderr
94		if err := cmd.Start(); err != nil {
95			t.Fatalf("start holder process: %v", err)
96		}
97		h := &holder{cmd: cmd, stdin: stdin, readyCh: make(chan string, 1)}
98		go func() {
99			scanner := bufio.NewScanner(stdout)
100			if scanner.Scan() {
101				h.readyCh <- scanner.Text()
102			} else {
103				h.readyCh <- ""
104			}
105		}()
106		t.Cleanup(func() { h.release(t) })
107		return h
108	}
109	
110	// waitReady 等待子进程完成 Open；返回其上报的第一行（READY 或 ERROR: ...）。
111	func (h *holder) waitReady(t *testing.T) string {
112		t.Helper()
113		select {
114		case line := <-h.readyCh:
115			return line
116		case <-time.After(15 * time.Second):
117			t.Fatal("holder process did not become ready in time")
118			return ""
119		}
120	}
121	
122	// release 让子进程关闭 Store 并等待其退出。
123	func (h *holder) release(t *testing.T) {
124		t.Helper()
125		if h.stdin != nil {
126			_ = h.stdin.Close()
127		}
128		done := make(chan error, 1)
129		go func() { done <- h.cmd.Wait() }()
130		select {
131		case err := <-done:
132			h.stdin = nil
133			// 子进程可能已被前一次 release 回收；只对仍在运行时的非零退出报错。
134			if err != nil && h.cmd.ProcessState != nil && h.cmd.ProcessState.ExitCode() != 0 {
135				t.Errorf("holder process exited with error: %v", err)
136			}
137		case <-time.After(15 * time.Second):
138			_ = h.cmd.Process.Kill()
139			t.Fatal("holder process did not exit after release")
140		}
141	}
