179		draft, err := s1.CreateDraft(doc, p.ID, enc.ID, Diagnosis, "初版诊断")
180		if err != nil {
181			t.Fatalf("create draft after rejected open: %v", err)
182		}
183		v1, err := s1.ActivateRecord(doc, draft.ID)
184		if err != nil {
185			t.Fatalf("activate after rejected open: %v", err)
186		}
187		v2, err := s1.CorrectRecord(doc, draft.ID, v1.Number, "复核后的诊断", "复核补录")
188		if err != nil {
189			t.Fatalf("correct after rejected open: %v", err)
190		}
191	
192		// 被拒绝的调用不能改变占用状态：第三次打开仍应立即失败。
193		reject("second rejection")
194	
195		// 查询历史、版本链与审计在原 Store 上完整可用。
196		hist, err := s1.EncounterRecords(doc, p.ID, enc.ID)
197		if err != nil {
198			t.Fatalf("query history: %v", err)
199		}
200		if len(hist) != 1 {
201			t.Fatalf("history len = %d, want 1", len(hist))
202		}
203		rh := hist[0]
204		if rh.CurrentVersion == nil || rh.CurrentVersion.ID != v2.ID || len(rh.Versions) != 2 {
205			t.Fatalf("version chain broken after rejected open: %+v", rh)
206		}
207		acts := auditActions(mustAudit(t, s1, p.ID))
208		if acts[ActionActivated] != 1 || acts[ActionCorrected] != 1 {
209			t.Fatalf("audit events changed by rejected open: %+v", acts)
210		}
211	
212		// 关闭后再开，已提交的患者、版本与审计原样保留。
213		if err := s1.Close(); err != nil {
