224		}
225		if got.Name != "锁互斥患者" || got.Source != SyntheticSource {
226			t.Fatalf("patient content changed across reopen: %+v", got)
227		}
228		reopened, err := s3.EncounterRecords(doc, p.ID, enc.ID)
229		if err != nil {
230			t.Fatalf("history after reopen: %v", err)
231		}
232		if len(reopened) != 1 || reopened[0].CurrentVersion == nil ||
233			reopened[0].CurrentVersion.ID != v2.ID || len(reopened[0].Versions) != 2 {
234			t.Fatalf("version history not preserved across reopen: %+v", reopened)
235		}
236		acts2 := auditActions(mustAudit(t, s3, p.ID))
237		if acts2[ActionActivated] != 1 || acts2[ActionCorrected] != 1 {
238			t.Fatalf("audit not preserved across reopen: %+v", acts2)
239		}
240	}
