21	// snapshotExchange 独立深拷贝一份交换作为预期基线（在篡改手中结果之前调用）。
22	func snapshotExchange(x Exchange) Exchange {
23		cp := x
24		recs := make([]PackagedRecord, len(x.Package.Records))
25		copy(recs, x.Package.Records)
26		cp.Package.Records = recs
27		if x.Receipt != nil {
28			r := *x.Receipt
29			cp.Receipt = &r
30		}
31		return cp
32	}
33	
34	// snapshotDelivery 独立深拷贝一份取包视图作为预期基线。
